INSERT INTO incoming_new_760 VALUES(2094,'من هي أم نبي الله إسماعيل عليه السلام التي تركها إبراهيم عليه السلام مع رضيعها عند الوادي غير ذي زرع وسعت بين الصفا والمروة؟','{"id":2094,"categoryId":"c30","category":"قصص الأنبياء","question":"من هي أم نبي الله إسماعيل عليه السلام التي تركها إبراهيم عليه السلام مع رضيعها عند الوادي غير ذي زرع وسعت بين الصفا والمروة؟","answer":"السيدة هاجر عليها السلام","points":200,"sourcePoints":200,"sourceIndex":2093,"difficulty":"سهل","options":["السيدة هاجر عليها السلام","السيدة مريم عليها السلام","السيدة سارة عليها السلام","السيدة آسية عليها السلام"],"optionsSource":"provided-question-bank","hint":"حرف الإجابة الأول: ا","hintSource":"generated-letter-hint"}');
INSERT INTO incoming_new_760 VALUES(2095,'كم عدد إخوة نبي الله يوسف عليه السلام الذين رآهم في منامه على هيئة أحد عشر كوكباً والشمس والقمر له ساجدين؟','{"id":2095,"categoryId":"c30","category":"قصص الأنبياء","question":"كم عدد إخوة نبي الله يوسف عليه السلام الذين رآهم في منامه على هيئة أحد عشر كوكباً والشمس والقمر له ساجدين؟","answer":"أحد عشر أخاً","points":200,"sourcePoints":200,"sourceIndex":2094,"difficulty":"سهل","options":["أحد عشر أخاً","اثنا عشر أخاً","سبعة إخوة","تسعة إخوة"],"optionsSource":"provided-question-bank","hint":"حرف الإجابة الأول: أ","hintSource":"generated-letter-hint"}');
INSERT INTO incoming_new_760 VALUES(2096,'ما اسم التابوت أو الصندوق الذي وضعت فيه أم موسى رضيعها وألقته في اليم (نهر النيل) بأمر الله وإلهامه ليأخذه فرعون؟','{"id":2096,"categoryId":"c30","category":"قصص الأنبياء","question":"ما اسم التابوت أو الصندوق الذي وضعت فيه أم موسى رضيعها وألقته في اليم (نهر النيل) بأمر الله وإلهامه ليأخذه فرعون؟","answer":"التابوت الملقى في اليم","points":200,"sourcePoints":200,"sourceIndex":2095,"difficulty":"سهل","options":["التابوت الملقى في اليم","الغار الصخري","السفينة المشحونة","البئر العميقة"],"optionsSource":"provided-question-bank","hint":"حرف الإجابة الأول: ا","hintSource":"generated-letter-hint"}');
INSERT INTO incoming_new_760 VALUES(2097,'من هي المرأة المؤمنة العظيمة زوجة فرعون التي آمنت بنبي الله موسى عليه السلام ودعت ربها: (رَبِّ ابْنِ لِي عِنْدَكَ بَيْتًا فِي الْجَنَّةِ وَنَجِّنِي مِنْ فِرْعَوْنَ وَعَمَلِهِ)؟','{"id":2097,"categoryId":"c30","category":"قصص الأنبياء","question":"من هي المرأة المؤمنة العظيمة زوجة فرعون التي آمنت بنبي الله موسى عليه السلام ودعت ربها: (رَبِّ ابْنِ لِي عِنْدَكَ بَيْتًا فِي الْجَنَّةِ وَنَجِّنِي مِنْ فِرْعَوْنَ وَعَمَلِهِ)؟","answer":"آسية بنت مزاحم عليها السلام","points":400,"sourcePoints":400,"sourceIndex":2096,"difficulty":"متوسط","options":["زليخا امرأة العزيز","بلقيس ملكة سبأ","أم جميل بنت حرب","آسية بنت مزاحم عليها السلام"],"optionsSource":"provided-question-bank","hint":"حرف الإجابة الأول: آ","hintSource":"generated-letter-hint"}');
INSERT INTO incoming_new_760 VALUES(2098,'ما اسم الشجرة ذات الأوراق العريضة الظليلة التي أنبتها الله على نبيه يونس عليه السلام حين نبذه الحوت بالعراء وهو سقيم؟','{"id":2098,"categoryId":"c30","category":"قصص الأنبياء","question":"ما اسم الشجرة ذات الأوراق العريضة الظليلة التي أنبتها الله على نبيه يونس عليه السلام حين نبذه الحوت بالعراء وهو سقيم؟","answer":"شجرة من يقطين القرع","points":400,"sourcePoints":400,"sourceIndex":2097,"difficulty":"متوسط","options":["شجرة من تين","شجرة من سدر","شجرة من يقطين القرع","شجرة من رمان"],"optionsSource":"provided-question-bank","hint":"حرف الإجابة الأول: ش","hintSource":"generated-letter-hint"}');
INSERT INTO incoming_new_760 VALUES(2099,'ماذا رأى ملك مصر في منامه في عهد نبي الله يوسف عليه السلام حين عجز الملأ عن تعبير رؤياه وفسرها يوسف بسبع سنين خصب وسبع سنين جدب؟','{"id":2099,"categoryId":"c30","category":"قصص الأنبياء","question":"ماذا رأى ملك مصر في منامه في عهد نبي الله يوسف عليه السلام حين عجز الملأ عن تعبير رؤياه وفسرها يوسف بسبع سنين خصب وسبع سنين جدب؟","answer":"سبع بقرات سمان يأكلهن سبع عجاف وسبع سنبلات خضر وأخر يابسات","points":400,"sourcePoints":400,"sourceIndex":2098,"difficulty":"متوسط","options":["شجرتين عظيمتين يخرج منهما نهر من لبن وعسل","أحد عشر كوكباً والشمس والقمر تسجد في السماء","طيراً يأكل من رأس رجلين في السجن","سبع بقرات سمان يأكلهن سبع عجاف وسبع سنبلات خضر وأخر يابسات"],"optionsSource":"provided-question-bank","hint":"حرف الإجابة الأول: س","hintSource":"generated-letter-hint"}');
INSERT INTO incoming_new_760 VALUES(2100,'من هو الأخ الشقيق لنبي الله يوسف عليه السلام من أمه وأبيه والذي أبقاه يوسف عنده في مصر بحيلة صواع الملك؟','{"id":2100,"categoryId":"c30","category":"قصص الأنبياء","question":"من هو الأخ الشقيق لنبي الله يوسف عليه السلام من أمه وأبيه والذي أبقاه يوسف عنده في مصر بحيلة صواع الملك؟","answer":"بنيامين","points":400,"sourcePoints":400,"sourceIndex":2099,"difficulty":"متوسط","options":["روبيل","يهوذا","شمعون","بنيامين"],"optionsSource":"provided-question-bank","hint":"حرف الإجابة الأول: ب","hintSource":"generated-letter-hint"}');
INSERT INTO incoming_new_760 VALUES(2101,'ما هي الآية الكونية التي طلبها نبي الله إبراهيم عليه السلام من ربه ليطمئن قلبه بكيفية إحياء الموتى كما في سورة البقرة؟','{"id":2101,"categoryId":"c30","category":"قصص الأنبياء","question":"ما هي الآية الكونية التي طلبها نبي الله إبراهيم عليه السلام من ربه ليطمئن قلبه بكيفية إحياء الموتى كما في سورة البقرة؟","answer":"أمره الله أن يأخذ أربعة من الطير فيصرهن إليه ثم يجعل على كل جبل منهن جزءاً ثم يدعوهن فيأتينه سعياً","points":400,"sourcePoints":400,"sourceIndex":2100,"difficulty":"متوسط","options":["أمره الله أن يضرب بعصاه الحجر فينفجر منه اثنتا عشرة عيناً","أمره الله أن ينظر إلى الجبل فلما تجلى ربه للجبل جعله دكاً","أمره الله أن يأخذ أربعة من الطير فيصرهن إليه ثم يجعل على كل جبل منهن جزءاً ثم يدعوهن فيأتينه سعياً","أمره الله أن يمسك الحديد بيده فيلين له كالعجين دون نار"],"optionsSource":"provided-question-bank","hint":"حرف الإجابة الأول: أ","hintSource":"generated-letter-hint"}');
INSERT INTO incoming_new_760 VALUES(2102,'في قصة نبي الله سليمان عليه السلام، من هو الكائن الصغير الذي قال لقومه كما في سورة النمل: (ادْخُلُوا مَسَاكِنَكُمْ لَا يَحْطِمَنَّكُمْ سُلَيْمَانُ وَجُنُودُهُ وَهُمْ لَا يَشْعُرُونَ) فتبسم سليمان ضاحكاً من قولها؟','{"id":2102,"categoryId":"c30","category":"قصص الأنبياء","question":"في قصة نبي الله سليمان عليه السلام، من هو الكائن الصغير الذي قال لقومه كما في سورة النمل: (ادْخُلُوا مَسَاكِنَكُمْ لَا يَحْطِمَنَّكُمْ سُلَيْمَانُ وَجُنُودُهُ وَهُمْ لَا يَشْعُرُونَ) فتبسم سليمان ضاحكاً من قولها؟","answer":"نملة في وادي النمل","points":400,"sourcePoints":400,"sourceIndex":2101,"difficulty":"متوسط","options":["فراشة في البستان","نحلة في الجبال","حمامة فوق الشجرة","نملة في وادي النمل"],"optionsSource":"provided-question-bank","hint":"حرف الإجابة الأول: ن","hintSource":"generated-letter-hint"}');
INSERT INTO incoming_new_760 VALUES(2103,'كيف علمت الجن بموت نبي الله سليمان عليه السلام بعد أن ظل متكئاً على عصاه؟','{"id":2103,"categoryId":"c30","category":"قصص الأنبياء","question":"كيف علمت الجن بموت نبي الله سليمان عليه السلام بعد أن ظل متكئاً على عصاه؟","answer":"ما دلهم على موته إلا دابة الأرض الأرضة تأكل منسأته عصاه فلما خرّ تبينت الجن","points":400,"sourcePoints":400,"sourceIndex":2102,"difficulty":"متوسط","options":["خسف القمر ثلاثة أيام متتالية في بيت المقدس","علموا بموته حين توقفت الرياح عن الجريان بأمره","ما دلهم على موته إلا دابة الأرض الأرضة تأكل منسأته عصاه فلما خرّ تبينت الجن","أخبرهم طائر الهدهد الذي عاد من أرض سبأ"],"optionsSource":"provided-question-bank","hint":"حرف الإجابة الأول: م","hintSource":"generated-letter-hint"}');
INSERT INTO incoming_new_760 VALUES(2104,'ما هي الآية (العلامة) التي جعلها الله لنبيه زكريا عليه السلام حين بشرته الملائكة بغلام اسمه يحيى وسأل ربه: (رَبِّ اجْعَلْ لِي آيَةً)؟','{"id":2104,"categoryId":"c30","category":"قصص الأنبياء","question":"ما هي الآية (العلامة) التي جعلها الله لنبيه زكريا عليه السلام حين بشرته الملائكة بغلام اسمه يحيى وسأل ربه: (رَبِّ اجْعَلْ لِي آيَةً)؟","answer":"آيتك ألا تكلم الناس ثلاثة أيام إلا رمزاً مع سلامة لسانك","points":400,"sourcePoints":400,"sourceIndex":2103,"difficulty":"متوسط","options":["آيتك أن ينبع الماء من محراب المسجد ثلاثة أيام","آيتك أن يخضرّ العود اليابس في يدك","آيتك أن تشرق الشمس من مغربها ساعة","آيتك ألا تكلم الناس ثلاثة أيام إلا رمزاً مع سلامة لسانك"],"optionsSource":"provided-question-bank","hint":"حرف الإجابة الأول: آ","hintSource":"generated-letter-hint"}');
INSERT INTO incoming_new_760 VALUES(2105,'في قصة نبي الله موسى عليه السلام في مدين، كم سنة اشترط الشيخ الصالح في مدين على موسى أن يأجره نفسه مقابل تزويجه إحدى ابنتيه؟','{"id":2105,"categoryId":"c30","category":"قصص الأنبياء","question":"في قصة نبي الله موسى عليه السلام في مدين، كم سنة اشترط الشيخ الصالح في مدين على موسى أن يأجره نفسه مقابل تزويجه إحدى ابنتيه؟","answer":"ثماني حجج سنوات فإن أتممت عشراً فمن عندك","points":600,"sourcePoints":600,"sourceIndex":2104,"difficulty":"صعب","options":["خمس حجج فإن أتممت سبعاً فمن عندك","اثنتي عشرة سنة كاملة دون نقصان","ثلاث حجج فإن أتممت خمساً فمن عندك","ثماني حجج سنوات فإن أتممت عشراً فمن عندك"],"optionsSource":"provided-question-bank","hint":"حرف الإجابة الأول: ث","hintSource":"generated-letter-hint"}');
INSERT INTO incoming_new_760 VALUES(2106,'ما هما الآيتان اللتان أخرج بهما موسى عليه السلام لفرعون في أول لقائه به كما في سورة الأعراف والشعراء؟','{"id":2106,"categoryId":"c30","category":"قصص الأنبياء","question":"ما هما الآيتان اللتان أخرج بهما موسى عليه السلام لفرعون في أول لقائه به كما في سورة الأعراف والشعراء؟","answer":"ألقى عصاه فإذا هي ثعبان مبين، ونزع يده فإذا هي بيضاء للناظرين من غير سوء","points":600,"sourcePoints":600,"sourceIndex":2105,"difficulty":"صعب","options":["أرسل الطوفان والجراد والقمل والضفادع والدم","فلق البحر اثني عشر طريقاً، وأنزل المن والسلوى","رفع جبل الطور فوق رؤوسهم كأنه ظلة","ألقى عصاه فإذا هي ثعبان مبين، ونزع يده فإذا هي بيضاء للناظرين من غير سوء"],"optionsSource":"provided-question-bank","hint":"حرف الإجابة الأول: أ","hintSource":"generated-letter-hint"}');
INSERT INTO incoming_new_760 VALUES(2107,'كم عدد الآيات المفصلات التي أرسلها الله على فرعون وقومه في مصر كما جُمعت في سورة الإسراء: (وَلَقَدْ آتَيْنَا مُوسَى تِسْعَ آيَاتٍ بَيِّنَاتٍ)؟','{"id":2107,"categoryId":"c30","category":"قصص الأنبياء","question":"كم عدد الآيات المفصلات التي أرسلها الله على فرعون وقومه في مصر كما جُمعت في سورة الإسراء: (وَلَقَدْ آتَيْنَا مُوسَى تِسْعَ آيَاتٍ بَيِّنَاتٍ)؟","answer":"تسع آيات بينات العصا، اليد، السنين، نقص الثمرات، الطوفان، الجراد، القمل، الضفادع، والدم","points":600,"sourcePoints":600,"sourceIndex":2106,"difficulty":"صعب","options":["خمس آيات بينات العصا، البحر، المن، السلوى، والحجر","سبع آيات بينات الريح، الصيحة، الخسف، الحاصب، والظلة","تسع آيات بينات العصا، اليد، السنين، نقص الثمرات، الطوفان، الجراد، القمل، الضفادع، والدم","اثنتا عشرة آية بعدد أسباط بني إسرائيل"],"optionsSource":"provided-question-bank","hint":"حرف الإجابة الأول: ت","hintSource":"generated-letter-hint"}');
INSERT INTO incoming_new_760 VALUES(2108,'في قصة نبي الله أيوب عليه السلام، بمَ أمره الله تعالى حين دعاه (أَنِّي مَسَّنِيَ الشَّيْطَانُ بِنُصْبٍ وَعَذَابٍ) ليشفى من مرضه كما في سورة ص؟','{"id":2108,"categoryId":"c30","category":"قصص الأنبياء","question":"في قصة نبي الله أيوب عليه السلام، بمَ أمره الله تعالى حين دعاه (أَنِّي مَسَّنِيَ الشَّيْطَانُ بِنُصْبٍ وَعَذَابٍ) ليشفى من مرضه كما في سورة ص؟","answer":"اركض برجلك هذا مغتسل بارد وشراب","points":600,"sourcePoints":600,"sourceIndex":2107,"difficulty":"صعب","options":["اشرب من ماء زمزم وادعُ الله عند السحر","كل من ثمر التين والزيتون أربعين صباحاً","اركض برجلك هذا مغتسل بارد وشراب","امسح بيدك اليمنى على موضع الألم سبع مرات"],"optionsSource":"provided-question-bank","hint":"حرف الإجابة الأول: ا","hintSource":"generated-letter-hint"}');
