INSERT INTO incoming_new_760 VALUES(2143,'من هو الأديب واللغوي النيسابوري صاحب كتاب (فقه اللغة وسر العربية) الذي رتّب فيه دقائق ألفاظ اللغة العربية ومعانيها؟','{"id":2143,"categoryId":"c32","category":"لغات ولهجات","question":"من هو الأديب واللغوي النيسابوري صاحب كتاب (فقه اللغة وسر العربية) الذي رتّب فيه دقائق ألفاظ اللغة العربية ومعانيها؟","answer":"أبو منصور الثعالبي","points":400,"sourcePoints":400,"sourceIndex":2142,"difficulty":"متوسط","options":["أبو منصور الثعالبي","ابن جني الموصلي","ابن فارس القزويني","الزمخشري الخوارزمي"],"optionsSource":"provided-question-bank","hint":"حرف الإجابة الأول: أ","hintSource":"generated-letter-hint"}');
INSERT INTO incoming_new_760 VALUES(2144,'من هو اللغوي صاحب المعجم الشهير (مقاييس اللغة) الذي أرجع فيه مفردات اللغة العربية إلى أصولها المعنوية الثلاثية؟','{"id":2144,"categoryId":"c32","category":"لغات ولهجات","question":"من هو اللغوي صاحب المعجم الشهير (مقاييس اللغة) الذي أرجع فيه مفردات اللغة العربية إلى أصولها المعنوية الثلاثية؟","answer":"أحمد بن فارس","points":400,"sourcePoints":400,"sourceIndex":2143,"difficulty":"متوسط","options":["الراغب الأصفهاني","أحمد بن فارس","الزبيدي","الفيومي"],"optionsSource":"provided-question-bank","hint":"حرف الإجابة الأول: أ","hintSource":"generated-letter-hint"}');
INSERT INTO incoming_new_760 VALUES(2145,'ما هو الفرق الدقيق في فقه اللغة العربية بين كلمتي (المائدة) و(الخوان)؟','{"id":2145,"categoryId":"c32","category":"لغات ولهجات","question":"ما هو الفرق الدقيق في فقه اللغة العربية بين كلمتي (المائدة) و(الخوان)؟","answer":"لا تُسمى المائدة مائدةً إلا إذا كان عليها طعام، فإذا لم يكن عليها طعام فهي خِوان","points":600,"sourcePoints":600,"sourceIndex":2144,"difficulty":"صعب","options":["المائدة لما يُؤكل باليد، والخوان لما يُشرب في الأقداح","لا تُسمى المائدة مائدةً إلا إذا كان عليها طعام، فإذا لم يكن عليها طعام فهي خِوان","المائدة تكون من الخشب فقط، والخوان يكون من النحاس أو الفضة","المائدة لطعام الغداء ظهراً، والخوان لطعام العشاء ليلاً"],"optionsSource":"provided-question-bank","hint":"حرف الإجابة الأول: ل","hintSource":"generated-letter-hint"}');
INSERT INTO incoming_new_760 VALUES(2146,'ما هو الفرق اللغوي في العربية الفصيحة بين (الكأس) و(القدح)؟','{"id":2146,"categoryId":"c32","category":"لغات ولهجات","question":"ما هو الفرق اللغوي في العربية الفصيحة بين (الكأس) و(القدح)؟","answer":"لا تُسمى الكأس كأساً إلا إذا كان فيها شراب، فإذا كانت فارغة فهي قدح أو كوب","points":600,"sourcePoints":600,"sourceIndex":2145,"difficulty":"صعب","options":["الكأس مصنوعة من الذهب فقط، والقدح مصنوع من الطين والفخار","الكأس للشراب الحار، والقدح للماء البارد فقط","لا تُسمى الكأس كأساً إلا إذا كان فيها شراب، فإذا كانت فارغة فهي قدح أو كوب","الكأس الصغيرة الحجم، والقدح الكبير الذي يتسع للترين"],"optionsSource":"provided-question-bank","hint":"حرف الإجابة الأول: ل","hintSource":"generated-letter-hint"}');
INSERT INTO incoming_new_760 VALUES(2147,'ماذا يُسمى صوت السيوف في المعركة، وصوت القلم عند الكتابة، وصوت الماء الجاري في اللغة العربية على الترتيب؟','{"id":2147,"categoryId":"c32","category":"لغات ولهجات","question":"ماذا يُسمى صوت السيوف في المعركة، وصوت القلم عند الكتابة، وصوت الماء الجاري في اللغة العربية على الترتيب؟","answer":"صليل السيوف، وصرير القلم، وخرير الماء","points":600,"sourcePoints":600,"sourceIndex":2146,"difficulty":"صعب","options":["صليل السيوف، وصرير القلم، وخرير الماء","رنين السيوف، وحسيس القلم، وزئير الماء","قعقعة السيوف، وخرير القلم، وحفيف الماء","صهيل السيوف، وحفيف القلم، وهدير الماء"],"optionsSource":"provided-question-bank","hint":"حرف الإجابة الأول: ص","hintSource":"generated-letter-hint"}');
