INSERT OR IGNORE INTO question_bank_versions SELECT 'pre-new-760-20261113',payload,revision,datetime('now') FROM question_bank WHERE id=1;
CREATE TABLE incoming_new_760 (id INTEGER PRIMARY KEY, question TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE new_760_id_guard (ok INTEGER NOT NULL CHECK(ok=1));
DROP TABLE new_760_id_guard;
UPDATE question_bank SET payload=json_set(payload,'$.questions',json((SELECT json_group_array(json(value)) FROM (SELECT value FROM json_each(question_bank.payload,'$.questions') UNION ALL SELECT data AS value FROM incoming_new_760 n WHERE NOT EXISTS (SELECT 1 FROM json_each(question_bank.payload,'$.questions') e WHERE json_extract(e.value,'$.question')=n.question))))),revision=revision+1 WHERE id=1;
DROP TABLE incoming_new_760;
